func TestSerializationJsonStructBytes(t *testing.T) {
	t.Parallel()
	// Define a source JSON string
	json := []byte(`{"f1":"QUJD","f2":"dGVzdA==","f3":null}`)

	// Create a new struct from the source JSON string
	struct1, _ := test.NewStructBytesFromJSON(json)

	// Serialize the struct to the JSON string
	json, _ = struct1.JSON()

	// Check the serialized JSON size
	require.NotEmpty(t, json)

	// Deserialize the struct from the JSON string
	struct2, _ := test.NewStructBytesFromJSON(json)

	require.EqualValues(t, len(struct2.F1), 3)
	require.EqualValues(t, struct2.F1[0], 65)
	require.EqualValues(t, struct2.F1[1], 66)
	require.EqualValues(t, struct2.F1[2], 67)
	require.NotNil(t, struct2.F2)
	require.EqualValues(t, len(*struct2.F2), 4)
	require.EqualValues(t, (*struct2.F2)[0], 116)
	require.EqualValues(t, (*struct2.F2)[1], 101)
	require.EqualValues(t, (*struct2.F2)[2], 115)
	require.EqualValues(t, (*struct2.F2)[3], 116)
	require.Nil(t, struct2.F3)
}

